window.weapons_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

// ── Полоска стата ──────────────────────────────────────────────────
weapons_elements.lib.Stat_bar=class extends e{
  constructor(w,color){
    super();color=color||0x44aa44;
    const bg=new A();bg.beginFill(0x0a100a,1);bg.drawRoundedRect(0,0,w,6,2);bg.endFill();
    this.fill=new A();this.fill.beginFill(color,1);this.fill.drawRoundedRect(0,0,w,6,2);this.fill.endFill();
    this.addChild(bg,this.fill);this[this.fill.name='fill']=this.fill;
  }
  setPercent(p){this.fill.scale.x=Math.max(0,Math.min(1,p));}
};

// ── Карточка оружия ────────────────────────────────────────────────
weapons_elements.lib.Weapon_card=class extends e{
  constructor(){
    super();
    // Фон
    this.bg_mc=new A();this._drawBg(false,false);
    this.addChild(this.bg_mc);
    // Область иконки
    const ib=new A();ib.beginFill(0x0c1a0c,1);ib.lineStyle(1,0x2a4a2a);ib.drawRoundedRect(8,8,80,80,6);ib.endFill();
    this.addChild(ib);
    const it=new z('',{fontFamily:'Arial',fontSize:38,align:'center'});it.anchor.set(0.5,0.5);it.x=48;it.y=48;
    this[it.name='icon_txt']=it;this.addChild(it);
    // Бейдж экипирован
    const eb=new A();eb.beginFill(0x20500a,1);eb.lineStyle(1,0x4a9a20);eb.drawRoundedRect(0,0,68,20,3);eb.endFill();
    const et=new z('ЭКИПИРОВАНО',{fontFamily:'Southbank LT',fontSize:9,fontWeight:'bold',fill:'#90e030',align:'center'});et.anchor.set(0.5,0.5);et.x=34;et.y=10;
    const ebw=new e();ebw.addChild(eb,et);ebw.x=6;ebw.y=70;ebw.visible=false;
    this[ebw.name='badge_equipped']=ebw;this.addChild(ebw);
    // Название
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:15,fontWeight:'bold',fill:'#d4e870',dropShadow:true,dropShadowDistance:1,dropShadowColor:'#000'});nt.x=98;nt.y=8;
    this[nt.name='name_txt']=nt;
    // Тип + уровень
    const tt=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#6a8a4a'});tt.x=98;tt.y=30;
    this[tt.name='type_txt']=tt;
    // Урон
    const dl=new z('Урон:',{fontFamily:'Arial',fontSize:11,fill:'#9ab06a'});dl.x=98;dl.y=50;
    const db=new weapons_elements.lib.Stat_bar(200,0xcc4422);db.x=144;db.y=54;
    const dv=new z('',{fontFamily:'Arial',fontSize:11,fill:'#e07050'});dv.x=350;dv.y=50;
    this[db.name='bar_damage']=db;this[dv.name='val_damage']=dv;
    // Скорострельность
    const sl=new z('Скор:',{fontFamily:'Arial',fontSize:11,fill:'#9ab06a'});sl.x=98;sl.y=68;
    const sb=new weapons_elements.lib.Stat_bar(200,0x2288cc);sb.x=144;sb.y=72;
    const sv=new z('',{fontFamily:'Arial',fontSize:11,fill:'#60a0e0'});sv.x=350;sv.y=68;
    this[sb.name='bar_speed']=sb;this[sv.name='val_speed']=sv;
    // Разделитель
    const div=new A();div.lineStyle(1,0x1e3c14,0.5);div.moveTo(8,95);div.lineTo(362,95);
    // Прочность
    const pl=new z('',{fontFamily:'Arial',fontSize:11,fill:'#7a9a5a'});pl.x=8;pl.y=100;
    this[pl.name='dur_label']=pl;
    const pb=new weapons_elements.lib.Stat_bar(348,0xaaaa22);pb.x=8;pb.y=118;
    this[pb.name='bar_dur']=pb;
    // Кнопка экипировать
    const eqbg=new A();eqbg.beginFill(0x1a3a0a,1);eqbg.lineStyle(1,0x3a7a1a);eqbg.drawRoundedRect(0,0,162,34,4);eqbg.endFill();
    const eqt=new z('ЭКИПИРОВАТЬ',{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:'#90d040',align:'center'});eqt.anchor.set(0.5,0.5);eqt.x=81;eqt.y=17;
    const eq=new e();eq.addChild(eqbg,eq._bg=eqbg,eqt);eq.x=8;eq.y=130;
    eq.interactive=true;eq.buttonMode=true;
    eq.on('mouseover',()=>eqbg.tint=0xcceeaa);eq.on('mouseout',()=>eqbg.tint=0xffffff);
    this[eq.name='butt_equip']=eq;
    // Кнопка улучшить
    const upbg=new A();upbg.beginFill(0x1a2a00,1);upbg.lineStyle(1,0x3a5a10);upbg.drawRoundedRect(0,0,162,34,4);upbg.endFill();
    const upt=new z('',{fontFamily:'Southbank LT',fontSize:11,fontWeight:'bold',fill:'#a0c050',align:'center'});upt.anchor.set(0.5,0.5);upt.x=81;upt.y=17;
    const up=new e();up.addChild(upbg,upt);up.x=180;up.y=130;
    up.interactive=true;up.buttonMode=true;
    up.on('mouseover',()=>upbg.tint=0xcceeaa);up.on('mouseout',()=>upbg.tint=0xffffff);
    this[up.name='butt_upgrade']=up;this[upt.name='upgrade_txt']=upt;
    // Оверлей «заблокировано»
    const lock=new A();lock.beginFill(0x000000,0.6);lock.drawRoundedRect(0,0,374,172,5);lock.endFill();
    const lbt=new z('',{fontFamily:'Southbank LT',fontSize:14,fontWeight:'bold',fill:'#607050',align:'center',wordWrap:true,wordWrapWidth:354});lbt.anchor.set(0.5,0.5);lbt.x=187;lbt.y=86;
    const lbw=new e();lbw.addChild(lock,lbt);lbw.visible=false;
    this[lbw.name='lock_overlay']=lbw;this[lbt.name='lock_txt']=lbt;
    // Кнопка купить
    const buybg=new A();buybg.beginFill(0x2a1a00,1);buybg.lineStyle(1,0x7a5010);buybg.drawRoundedRect(0,0,200,38,4);buybg.endFill();
    const buyt=new z('',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#e0a030',align:'center'});buyt.anchor.set(0.5,0.5);buyt.x=100;buyt.y=19;
    const buy=new e();buy.addChild(buybg,buyt);buy.x=87;buy.y=118;buy.visible=false;
    buy.interactive=true;buy.buttonMode=true;
    buy.on('mouseover',()=>buybg.tint=0xeeddaa);buy.on('mouseout',()=>buybg.tint=0xffffff);
    this[buy.name='butt_buy']=buy;this[buyt.name='buy_txt']=buyt;
    this.addChild(nt,tt,dl,db,dv,sl,sb,sv,div,pl,pb,eq,up,lbw,buy);
  }
  _drawBg(equipped,locked){
    this.bg_mc.clear();
    if(equipped){this.bg_mc.beginFill(0x0d2008,0.95);this.bg_mc.lineStyle(2,0x3a7a20,0.9);}
    else if(locked){this.bg_mc.beginFill(0x080d06,0.7);this.bg_mc.lineStyle(1,0x141e10,0.5);}
    else{this.bg_mc.beginFill(0x0a1608,0.92);this.bg_mc.lineStyle(1,0x1e3c14,0.8);}
    this.bg_mc.drawRoundedRect(0,0,374,172,5);this.bg_mc.endFill();
  }
  setState(equipped,locked){
    this._drawBg(equipped,locked);
    this.badge_equipped.visible=equipped;
    this.lock_overlay.visible=locked;
    this.butt_equip.visible=!locked;
    this.butt_upgrade.visible=!locked;
    this.butt_buy.visible=locked;
    this.bar_damage.visible=!locked;this.bar_speed.visible=!locked;
    this.bar_dur.visible=!locked;this.dur_label.visible=!locked;
    this.val_damage.visible=!locked;this.val_speed.visible=!locked;
  }
};

// ── Главное окно Оружия ────────────────────────────────────────────
weapons_elements.lib.Weapons_win=class extends e{
  constructor(){
    super();
    const wb=new A();wb.beginFill(0x060c04,0.97);wb.lineStyle(2,0x2a5a18,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();
    this.addChild(wb);
    const hb=new A();hb.beginFill(0x0a1c06,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x2a5a18,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);
    this.addChild(hb,hl);
    const ttl=new z('ОРУЖИЕ',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#c8d840',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});
    ttl.x=20;ttl.y=12;this.addChild(ttl);
    // Экипировано сейчас
    const el=new z('Экипировано:',{fontFamily:'Southbank LT',fontSize:11,fill:'#5a7a3a'});el.x=240;el.y=16;this.addChild(el);
    const et=new z('',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#b0e040'});et.x=340;et.y=13;
    this[et.name='equipped_label']=et;this.addChild(et);
    // Закрыть
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;
    cl.interactive=true;cl.buttonMode=true;
    cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // Сетка 3×2 карточек
    const grid=new e();grid.x=10;grid.y=50;
    for(let i=0;i<6;i++){
      const cd=new weapons_elements.lib.Weapon_card();
      cd.x=(i%3)*(374+8);cd.y=Math.floor(i/3)*(172+8);
      grid['card_'+i]=cd;grid.addChild(cd);
    }
    this[grid.name='wgrid']=grid;this.addChild(grid);
    // Подсказка снизу
    const hint=new z('Улучшение оружия увеличивает урон по боссам и КПП Зоны.',{fontFamily:'Arial',fontSize:11,fill:'#4a6a3a',fontStyle:'italic'});
    hint.x=20;hint.y=508;this.addChild(hint);
  }
};

// ── Root MovieClip ─────────────────────────────────────────────────
weapons_elements.lib.weapons_elements=class extends n{
  constructor(){
    super({duration:1,framerate:30});
    const b=new weapons_elements.lib.Weapons_win();
    this[b.name='weapons_win']=b;this.addChild(b);
  }
};
weapons_elements.stage=weapons_elements.lib.weapons_elements}};
